mapper.select:
SELECT m.id,v.width,v.height FROM media_assets m JOIN media_variants v ON v.media_id=m.id AND v.kind='display'
JOIN post_media b ON b.media_id=m.id JOIN posts p ON p.id=b.post_id WHERE p.id=#{targetId} AND p.status IN ('pending','rejected','visible','hidden') AND (p.status IN ('pending','rejected') OR p.expires_at IS NULL OR p.expires_at>#{now}) JOIN comment_media b ON b.media_id=m.id JOIN comments c ON c.id=b.comment_id JOIN posts p ON p.id=c.post_id WHERE c.id=#{targetId} AND c.status IN ('pending','rejected','visible','hidden') AND (c.status IN ('pending','rejected') OR c.expires_at IS NULL OR c.expires_at>#{now}) AND p.scope='public' AND p.status='visible' AND p.expires_at>#{now}
AND m.status='approved' AND m.deleted_at IS NULL ORDER BY b.position
